package com.clavis.reader;
import android.app.*;
import android.content.*;
import android.database.Cursor;
import android.net.Uri;
import android.os.Environment;
import android.webkit.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.zip.ZipFile;
final class EbookDownloads {
 private static final Object LOCK=new Object();
 static JSONObject records(Context c){synchronized(LOCK){try{return new JSONObject(c.getSharedPreferences("ebook_downloads",0).getString("jobs","{}"));}catch(Exception e){return new JSONObject();}}}
 private static void record(Context c,long id,JSONObject entry){synchronized(LOCK){JSONObject all=records(c);try{all.put(Long.toString(id),entry);}catch(Exception ignored){}c.getSharedPreferences("ebook_downloads",0).edit().putString("jobs",all.toString()).apply();}}
 static void offer(MainActivity a,String url,String agent,String disposition,String mime,String referer){try{if(!"https".equalsIgnoreCase(Uri.parse(url).getScheme()))throw new IllegalArgumentException("Use a direct HTTPS PDF or EPUB download link.");String name=cleanName(URLUtil.guessFileName(url,disposition,mime));String lower=name.toLowerCase(Locale.ROOT);String kind=lower.endsWith(".pdf")||"application/pdf".equalsIgnoreCase(mime)?"PDF":lower.endsWith(".epub")||"application/epub+zip".equalsIgnoreCase(mime)?"EPUB":"";if(kind.isEmpty())throw new IllegalArgumentException("Choose the site's PDF or EPUB download option.");if(!lower.endsWith("."+kind.toLowerCase(Locale.ROOT)))name+="."+kind.toLowerCase(Locale.ROOT);String fileName=name,bookKind=kind;
  if(SharedDownloads.folder(a)==null){new AppDialog.Builder(a).setTitle("Choose download folder").setMessage("Choose Clavis once, then tap the book download again.").setPositiveButton("Choose folder",(dialog,which)->SharedDownloads.choose(a)).setNegativeButton("Cancel",null).show();return;}new AppDialog.Builder(a).setTitle("Download ebook").setMessage(fileName+"\n\nThe completed "+kind+" will be added to your library.").setPositiveButton("Download",(d,n)->{try{DownloadManager.Request request=new DownloadManager.Request(Uri.parse(url));request.setTitle(fileName);request.setDescription("Clavis ebook download");request.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);request.setDestinationInExternalFilesDir(a,Environment.DIRECTORY_DOWNLOADS,"Ebooks/"+UUID.randomUUID()+"-"+fileName);if(agent!=null&&!agent.isEmpty())request.addRequestHeader("User-Agent",agent);String cookie=CookieManager.getInstance().getCookie(url);if(cookie!=null&&!cookie.isEmpty())request.addRequestHeader("Cookie",cookie);if(referer!=null)request.addRequestHeader("Referer",referer);long id=a.getSystemService(DownloadManager.class).enqueue(request);JSONObject entry=new JSONObject().put("name",fileName).put("kind",bookKind).put("imported",false);record(a,id,entry);a.startActivity(new Intent(a,DownloadsActivity.class));}catch(Exception e){error(a,e.getMessage());}}).setNegativeButton("Cancel",null).show();
 }catch(Exception e){error(a,e.getMessage());}}
 private static String cleanName(String value){StringBuilder out=new StringBuilder();for(char c:value.toCharArray()){out.append(Character.isISOControl(c)||c==47||c==92||c==58||c==42||c==63||c==34||c==60||c==62||c==124?'_':c);if(out.length()>=170)break;}return out.length()==0?"ebook":out.toString();}
 private static void error(MainActivity a,String text){new AppDialog.Builder(a).setTitle("Ebook download").setMessage(text).setPositiveButton("OK",null).show();}
 static void importComplete(Context c,long id){JSONObject all=records(c),entry=all.optJSONObject(Long.toString(id));if(entry==null||entry.optBoolean("imported"))return;try(Cursor cursor=c.getSystemService(DownloadManager.class).query(new DownloadManager.Query().setFilterById(id))){if(cursor==null||!cursor.moveToFirst()||cursor.getInt(cursor.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS))!=DownloadManager.STATUS_SUCCESSFUL)return;String raw=cursor.getString(cursor.getColumnIndexOrThrow(DownloadManager.COLUMN_LOCAL_URI));Uri uri=Uri.parse(raw);File file=new File(uri.getPath()),root=c.getExternalFilesDir(Environment.DIRECTORY_DOWNLOADS);if(!"file".equals(uri.getScheme())||root==null||!file.getCanonicalPath().startsWith(root.getCanonicalPath()+File.separator))throw new IOException("Downloaded file is not in Clavis's download folder");String kind=entry.getString("kind");if(kind.equals("PDF")){try(InputStream in=new FileInputStream(file)){byte[] header=new byte[5];if(in.read(header)!=5||!new String(header,java.nio.charset.StandardCharsets.US_ASCII).equals("%PDF-"))throw new IOException("The site returned a page instead of a PDF. Check the website login and try again.");}}else try(ZipFile zip=new ZipFile(file)){if(zip.getEntry("META-INF/container.xml")==null)throw new IOException("The download is not a valid EPUB book");}
  Uri destination=SharedDownloads.folder(c);if(destination==null)throw new IOException("Choose Clavis in Download settings");uri=SharedDownloads.copyFile(c,file,destination);synchronized(Store.class){ArrayList<Book> books=Store.load(c);String bookUri=uri.toString();if(books.stream().noneMatch(b->b.uri.equals(bookUri))){books.add(new Book(bookUri,entry.getString("name").replaceFirst("(?i)\\.(pdf|epub)$",""),kind));Store.save(c,books);}}entry.put("uri",uri.toString()).put("imported",true).remove("error");record(c,id,entry);file.delete();
 }catch(Exception e){try{entry.put("error",e.getMessage());record(c,id,entry);}catch(Exception ignored){}}}
 static int render(MainActivity a,LinearLayout parent){JSONObject all=records(a);int count=0;Iterator<String> keys=all.keys();while(keys.hasNext()){String key=keys.next();JSONObject entry=all.optJSONObject(key);if(entry==null)continue;long id;try{id=Long.parseLong(key);}catch(Exception e){continue;}count++;LinearLayout card=a.column();card.setPadding(a.dp(14),a.dp(12),a.dp(14),a.dp(12));card.setBackground(a.bg(AppTheme.surface,16));card.addView(a.text(entry.optString("name"),16,MainActivity.INK,true));String state="Queued";int status=0;long bytes=0,total=0;try(Cursor c=a.getSystemService(DownloadManager.class).query(new DownloadManager.Query().setFilterById(id))){if(c!=null&&c.moveToFirst()){status=c.getInt(c.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));bytes=c.getLong(c.getColumnIndexOrThrow(DownloadManager.COLUMN_BYTES_DOWNLOADED_SO_FAR));total=c.getLong(c.getColumnIndexOrThrow(DownloadManager.COLUMN_TOTAL_SIZE_BYTES));if(status==DownloadManager.STATUS_RUNNING)state="Downloading";else if(status==DownloadManager.STATUS_PAUSED)state="Waiting for network";else if(status==DownloadManager.STATUS_FAILED)state="Download failed ("+c.getInt(c.getColumnIndexOrThrow(DownloadManager.COLUMN_REASON))+")";else if(status==DownloadManager.STATUS_SUCCESSFUL)state=entry.optBoolean("imported")?"Added to "+entry.optString("kind")+" library":"Download complete - importing";}else state="Download unavailable";}catch(Exception e){state="Download unavailable";}
  if(status==DownloadManager.STATUS_SUCCESSFUL&&!entry.optBoolean("imported")&&!entry.has("error")){long downloadId=id;a.io.execute(()->importComplete(a.getApplicationContext(),downloadId));}card.addView(a.text(entry.optString("error",state),12,MainActivity.MUTED,false));ProgressBar progress=new ProgressBar(a,null,android.R.attr.progressBarStyleHorizontal);AppTheme.tintProgress(progress);progress.setMax(1000);progress.setIndeterminate(total<=0&&status!=DownloadManager.STATUS_SUCCESSFUL&&status!=DownloadManager.STATUS_FAILED);if(total>0)progress.setProgress((int)(bytes*1000/total));card.addView(progress,new LinearLayout.LayoutParams(-1,a.dp(24)));if(entry.optBoolean("imported"))card.addView(a.button("Open folder",()->SharedDownloads.open(a)));parent.addView(card);a.space(parent,12);}return count;}
}
